import { useState, useCallback } from "react";
import "./App.css";
import BookList from "./components/BookList";
import BookForm from "./components/BookForm";

function App() {
  const [refreshKey, setRefreshKey] = useState(0);
  const handleBookCreated = useCallback(() => {
    setRefreshKey((k) => k + 1);
  }, []);

  return (
    <div className="app">
      <h1>BookTrack — I miei libri</h1>
      <BookForm onBookCreated={handleBookCreated} />
      <BookList refreshKey={refreshKey} />
    </div>
  );
}

export default App

CREATE TABLE IF NOT EXISTS books (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    author TEXT NOT NULL,
    status TEXT NOT NULL CHECK (status IN ('to-read', 'reading', 'done'))
);

from fastapi import APIRouter, HTTPException

from database import get_connection
from models import Book, BookCreate, BookUpdate

router = APIRouter(prefix="/books", tags=["books"])


@router.get("", response_model=list[Book])
def list_books():
    conn = get_connection()
    try:
        rows = conn.execute("SELECT id, title, author, status FROM books").fetchall()
        return [dict(row) for row in rows]
    finally:
        conn.close()


@router.post("", response_model=Book, status_code=201)
def create_book(book: BookCreate):
    conn = get_connection()
    try:
        cursor = conn.execute(
            "INSERT INTO books (title, author, status) VALUES (?, ?, ?)",
            (book.title, book.author, book.status),
        )
        conn.commit()
        new_id = cursor.lastrowid
        row = conn.execute(
            "SELECT id, title, author, status FROM books WHERE id = ?", (new_id,)
        ).fetchone()
        return dict(row)
    finally:
        conn.close()


@router.patch("/{book_id}", response_model=Book)
def update_book(book_id: int, book: BookUpdate):
    conn = get_connection()
    try:
        # Verify the book exists
        existing = conn.execute(
            "SELECT id, title, author, status FROM books WHERE id = ?", (book_id,)
        ).fetchone()
        if existing is None:
            raise HTTPException(status_code=404, detail="Book not found")

        # Build dynamic SET clause for provided fields only
        fields = book.model_dump(exclude_unset=True)
        if not fields:
            raise HTTPException(status_code=400, detail="No fields to update")

        set_clause = ", ".join(f"{k} = ?" for k in fields)
        values = list(fields.values())
        values.append(book_id)

        conn.execute(
            f"UPDATE books SET {set_clause} WHERE id = ?", values
        )
        conn.commit()

        row = conn.execute(
            "SELECT id, title, author, status FROM books WHERE id = ?", (book_id,)
        ).fetchone()
        return dict(row)
    finally:
        conn.close()


@router.delete("/{book_id}", status_code=204)
def delete_book(book_id: int):
    conn = get_connection()
    try:
        existing = conn.execute(
            "SELECT id FROM books WHERE id = ?", (book_id,)
        ).fetchone()
        if existing is None:
            raise HTTPException(status_code=404, detail="Book not found")

        conn.execute("DELETE FROM books WHERE id = ?", (book_id,))
        conn.commit()
    finally:
        conn.close()

const BASE_URL = "http://localhost:8000/books";

export async function listBooks() {
  const res = await fetch(BASE_URL);
  if (!res.ok) throw new Error("Failed to fetch books");
  return res.json();
}

export async function createBook(book) {
  const res = await fetch(BASE_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(book),
  });
  if (!res.ok) throw new Error("Failed to create book");
  return res.json();
}

export async function updateBookStatus(id, status) {
  const res = await fetch(`${BASE_URL}/${id}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ status }),
  });
  if (!res.ok) throw new Error("Failed to update book");
  return res.json();
}

import { useEffect, useState } from "react";
import { listBooks } from "../api";

export default function BookList({ refreshKey }) {
  const [books, setBooks] = useState([]);
  const [error, setError] = useState(null);

  useEffect(() => {
    let cancelled = false;
    listBooks()
      .then((data) => {
        if (!cancelled) setBooks(data);
      })
      .catch((err) => {
        if (!cancelled) setError(err.message);
      });
    return () => {
      cancelled = true;
    };
  }, [refreshKey]);

  if (error) return <p className="error">Error: {error}</p>;

  if (books.length === 0) return <p>No books yet. Add one!</p>;

  return (
    <ul className="book-list">
      {books.map((book) => (
        <li key={book.id} className="book-item">
          <strong>{book.title}</strong> — {book.author}
          <span className={`status status-${book.status}`}>{book.status}</span>
        </li>
      ))}
    </ul>
  );
}
